begin;
alter table public.tutor_published_tasks add column statement_doc jsonb, add column bank_number integer check(bank_number between 1 and 27), add column bank_serial bigint generated by default as identity, add column has_solution boolean not null default false;
create unique index tutor_bank_serial_idx on public.tutor_published_tasks(bank_serial);
create index tutor_bank_number_idx on public.tutor_published_tasks(bank_number) where bank_number is not null;
create table tutor_private.bank_drafts(module_id uuid primary key references public.tutor_modules(id),owner_id uuid not null references auth.users(id));
alter table tutor_private.bank_drafts enable row level security;
revoke all on tutor_private.bank_drafts from public,anon,authenticated;
create table public.tutor_bank_tasks(task_id uuid primary key references public.tutor_published_tasks(id),owner_id uuid not null references auth.users(id),number integer not null check(number between 1 and 27),deleted boolean not null default false);
create index tutor_bank_owner_idx on public.tutor_bank_tasks(owner_id);
create table public.tutor_exam_variants(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id),title text not null check(length(btrim(title)) between 1 and 200),items jsonb not null default '{}',revision integer not null default 0,visible boolean not null default false,deleted boolean not null default false);
create index tutor_exam_owner_idx on public.tutor_exam_variants(owner_id);
create table public.tutor_exam_publications(variant_id uuid not null references public.tutor_exam_variants(id),revision integer not null,title text not null,items jsonb not null,primary key(variant_id,revision));
create table tutor_private.exam_keys(variant_id uuid not null,revision integer not null,keys jsonb not null,primary key(variant_id,revision),foreign key(variant_id,revision) references public.tutor_exam_publications(variant_id,revision));
create table public.tutor_exam_runs(id uuid primary key default gen_random_uuid(),student_id uuid not null references auth.users(id),variant_id uuid not null,revision integer not null,answers jsonb not null default '{}',result jsonb,started_at timestamptz not null default clock_timestamp(),completed_at timestamptz,foreign key(variant_id,revision) references public.tutor_exam_publications(variant_id,revision));
create index tutor_exam_runs_user_idx on public.tutor_exam_runs(student_id,started_at desc);
create index tutor_exam_runs_pub_idx on public.tutor_exam_runs(variant_id,revision);
alter table public.tutor_attempts add column exam_run_id uuid references public.tutor_exam_runs(id);
create index tutor_attempts_exam_idx on public.tutor_attempts(exam_run_id);
do $$ declare t text;begin foreach t in array array['tutor_bank_tasks','tutor_exam_variants','tutor_exam_publications','tutor_exam_runs'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t); end loop;end $$;
alter table tutor_private.exam_keys enable row level security;
revoke all on tutor_private.exam_keys from public,anon,authenticated;
-- New data are only exposed through the checked API. Keys never enter public tables.
create table tutor_private.bank_image_grants(user_id uuid not null references auth.users(id),path text not null,primary key(user_id,path));
alter table tutor_private.bank_image_grants enable row level security;
revoke all on tutor_private.bank_image_grants from public,anon,authenticated;
create function tutor_private.grant_bank_images(uid uuid,doc text) returns void language plpgsql security invoker set search_path='' as $$begin
 if doc is not null and doc<>'' then insert into tutor_private.bank_image_grants select uid,x#>>'{}' from jsonb_path_query(doc::jsonb,'$.** ? (@.type == "bankImage").attrs.path') x on conflict do nothing;end if;
end $$;
revoke all on function tutor_private.grant_bank_images(uuid,text) from public,anon,authenticated;
create function tutor_private.bank_image_read(path text) returns boolean language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and tutor_private.code_session_active() and (
 exists(select 1 from tutor_private.bank_image_grants g where g.user_id=auth.uid() and g.path=$1) or
 exists(select 1 from public.tutor_published_tasks t where t.active and t.bank_number is not null and tutor_private.can_read_module(t.module_id) and jsonb_path_exists(t.statement_doc,'$.** ? (@.type == "bankImage" && @.attrs.path == $path)',jsonb_build_object('path',$1))) or
 exists(select 1 from public.tutor_homework_items i where tutor_private.can_read_homework(i.homework_id) and jsonb_path_exists(i.snapshot->'statement_doc','$.** ? (@.type == "bankImage" && @.attrs.path == $path)',jsonb_build_object('path',$1))) or
 exists(select 1 from public.tutor_attempts a where a.student_id=auth.uid() and jsonb_path_exists(a.task_snapshot->'statement_doc','$.** ? (@.type == "bankImage" && @.attrs.path == $path)',jsonb_build_object('path',$1))) or
 exists(select 1 from public.tutor_exam_runs r join public.tutor_exam_publications p using(variant_id,revision) where r.student_id=auth.uid() and jsonb_path_exists(p.items,'$.** ? (@.type == "bankImage" && @.attrs.path == $path)',jsonb_build_object('path',$1)))
 );$$;
revoke all on function tutor_private.bank_image_read(text) from public,anon;
grant execute on function tutor_private.bank_image_read(text) to authenticated;
create policy tutor_bank_images_read on storage.objects for select to authenticated using(bucket_id='tutor-images' and tutor_private.bank_image_read(name));
create function tutor_private.bank_api(action text,p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();admin boolean:=tutor_private.is_teacher() and not coalesce((p->>'preview')::boolean,false); base jsonb; v public.tutor_exam_variants; r public.tutor_exam_runs; tid uuid; mid uuid; topid uuid; sid uuid; rev integer; x jsonb; snapshots jsonb:='[]'; keys jsonb:='{}'; k jsonb; task jsonb; grade jsonb; results jsonb:='[]'; n integer; score integer:=0; rid uuid;
begin
 if uid is null then raise exception 'Требуется вход в аккаунт' using errcode='42501';end if;
 if not tutor_private.code_session_active() then raise exception 'Доступ закрыт или код обновлён' using errcode='42501';end if;
 if pg_column_size(p)>2000000 then raise exception 'Слишком большой запрос';end if;
 if action='bank_prepare' then
  if not admin then raise exception 'Требуется роль преподавателя';end if;
  select id into sid from public.tutor_sections where number=1 limit 1;
  x:=tutor_private.workspace_api('topic_save',jsonb_build_object('section_id',sid,'title','Банк заданий'));
  x:=tutor_private.workspace_api('module_create',jsonb_build_object('topic_id',x->'id','title','Задание банка'));
  insert into tutor_private.bank_drafts values((x->>'id')::uuid,uid);
  return jsonb_build_object('module_id',x->'id');
 end if;
 if action='bank_edit' then
  if not admin or not exists(select 1 from public.tutor_bank_tasks where task_id=(p->>'id')::uuid and owner_id=uid and not deleted) then raise exception 'Задание недоступно';end if;
  select to_jsonb(t)||jsonb_build_object('answer',k.answer,'solution_doc',nullif(k.solution,'')::jsonb,'ignore_case',k.ignore_case,'collapse_spaces',k.collapse_spaces) into x from public.tutor_published_tasks t join tutor_private.published_keys k on k.task_id=t.id where t.id=(p->>'id')::uuid;
  return x;
 end if;
 if action='bank_save' then
  if not admin then raise exception 'Требуется роль преподавателя' using errcode='42501';end if;
  n:=(p->>'number')::integer;if n not between 1 and 27 then raise exception 'Выберите номер 1–27';end if;
  tid:=(p->>'id')::uuid;
  if tid is null then
   select module_id into mid from tutor_private.bank_drafts where module_id=(p->>'module_id')::uuid and owner_id=uid for update;
   if mid is null then raise exception 'Черновик недоступен';end if;
  else
   select t.module_id into mid from public.tutor_bank_tasks b join public.tutor_published_tasks t on t.id=b.task_id where b.task_id=tid and b.owner_id=uid and not b.deleted for update of b;
   if mid is null then raise exception 'Задание недоступно' using errcode='42501';end if;
  end if;
  if jsonb_typeof(p->'statement_doc') is distinct from 'object' or p->'statement_doc'->>'type' is distinct from 'doc' or jsonb_typeof(p->'solution_doc') is distinct from 'object' then raise exception 'Проверьте формат условия и решения';end if;
  if p->>'type' not in ('number','text') then raise exception 'Выберите формат ответа';end if;
  x:=tutor_private.workspace_api('task_save',jsonb_build_object('id',tid,'module_id',mid,'type',p->>'type','title','Задание №'||n,'statement',p->>'statement','answer',p->'answer','solution',coalesce((p->'solution_doc')::text,''),'difficulty',1,'reveal','never','ignore_case',coalesce((p->>'ignore_case')::boolean,false),'collapse_spaces',coalesce((p->>'collapse_spaces')::boolean,false)));
  tid:=(x->>'id')::uuid;
  for x in select * from jsonb_path_query(jsonb_build_array(p->'statement_doc',p->'solution_doc'),'$.** ? (@.type == "bankImage").attrs.path') loop
   if (x#>>'{}') not like mid::text||'/%' or not exists(select 1 from storage.objects where bucket_id='tutor-images' and name=x#>>'{}') then raise exception 'Изображение недоступно';end if;
  end loop;
  select revision into rev from public.tutor_modules where id=mid;
  x:=tutor_private.workspace_api('module_save',jsonb_build_object('module_id',mid,'revision',rev,'title','Задание №'||n,'blocks',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'type','practice','task_id',tid))));
  perform tutor_private.workspace_api('publish',jsonb_build_object('module_id',mid,'revision',x->'revision'));
  update public.tutor_published_tasks set statement_doc=p->'statement_doc',bank_number=n,has_solution=coalesce((p->>'has_solution')::boolean,false) where id=tid;
  insert into public.tutor_bank_tasks(task_id,owner_id,number) values(tid,uid,n) on conflict(task_id) do update set number=n;
  delete from tutor_private.bank_drafts where module_id=mid;
  return jsonb_build_object('id',tid);
 end if;
 if action='bank_delete' then
  if not admin then raise exception 'Требуется роль преподавателя';end if;
  update public.tutor_bank_tasks set deleted=true where task_id=(p->>'id')::uuid and owner_id=uid returning task_id into tid;
  if tid is null then raise exception 'Задание недоступно';end if;
  update public.tutor_published_tasks set active=false where id=tid;
  return '{}';
 end if;
 if action='bank_reveal' then
  if not exists(select 1 from public.tutor_bank_tasks where task_id=(p->>'id')::uuid and not deleted) then raise exception 'Задание недоступно';end if;
  if exists(select 1 from public.tutor_exam_runs er join public.tutor_exam_publications ep using(variant_id,revision) where er.student_id=uid and er.completed_at is null and exists(select 1 from jsonb_array_elements(ep.items) it where it->>'id'=p->>'id')) then raise exception 'Ответ доступен после завершения варианта';end if;
  select to_jsonb(t) into task from public.tutor_published_tasks t where t.id=(p->>'id')::uuid and t.active and tutor_private.can_read_module(t.module_id);
  if task is null then raise exception 'Задание недоступно';end if;
  select to_jsonb(pk) into k from tutor_private.published_keys pk where pk.task_id=(p->>'id')::uuid;
  if p->>'part'='solution' then perform tutor_private.grant_bank_images(uid,k->>'solution');end if;
  return jsonb_build_object('answer',k->'answer','solution_doc',case when task->>'has_solution'='true' and p->>'part'='solution' then (k->>'solution')::jsonb else null end);
 end if;
 if action in ('variant_save','variant_publish','variant_hide','variant_delete') then
  if not admin then raise exception 'Требуется роль преподавателя' using errcode='42501';end if;
  if action='variant_save' and p->>'id' is null then
   insert into public.tutor_exam_variants(owner_id,title) values(uid,p->>'title') returning * into v;
  else
   select * into v from public.tutor_exam_variants where id=(p->>'id')::uuid and owner_id=uid and not deleted for update;
   if v.id is null then raise exception 'Вариант недоступен';end if;
  end if;
  if action='variant_save' then
   if jsonb_typeof(p->'items') is distinct from 'object' then raise exception 'Проверьте состав варианта';end if;
   for x in select jsonb_build_object('n',key,'id',value) from jsonb_each_text(p->'items') loop
    if (x->>'n')::integer not between 1 and 27 or not exists(select 1 from public.tutor_bank_tasks b where b.task_id=(x->>'id')::uuid and b.number=(x->>'n')::integer and b.owner_id=uid and not b.deleted) then raise exception 'Задание не соответствует номеру';end if;
   end loop;
   update public.tutor_exam_variants set title=p->>'title',items=p->'items' where id=v.id;
  elsif action='variant_publish' then
   perform 1 from public.tutor_bank_tasks b where b.task_id in(select value::uuid from jsonb_each_text(v.items)) order by b.task_id for share;
   for n in 1..27 loop
    select to_jsonb(t) into task from public.tutor_published_tasks t join public.tutor_bank_tasks b on b.task_id=t.id where t.id=(v.items->>n::text)::uuid and b.number=n and b.owner_id=uid and not b.deleted and t.active;
    if task is null then raise exception 'Заполните все 27 номеров';end if;
    snapshots:=snapshots||jsonb_build_array(task);
    select to_jsonb(pk)-'task_id' into k from tutor_private.published_keys pk where pk.task_id=(task->>'id')::uuid;
    keys:=keys||jsonb_build_object(task->>'id',k);
   end loop;
   rev:=v.revision+1;
   insert into public.tutor_exam_publications values(v.id,rev,v.title,snapshots);
   insert into tutor_private.exam_keys values(v.id,rev,keys);
   update public.tutor_exam_variants set revision=rev,visible=true where id=v.id;
  else update public.tutor_exam_variants set visible=false,deleted=action='variant_delete' where id=v.id;
  end if;
  return jsonb_build_object('id',v.id);
 end if;
 if action='exam_start' then
  select * into v from public.tutor_exam_variants where id=(p->>'id')::uuid and visible and not deleted;
  if v.id is null then raise exception 'Вариант недоступен';end if;
  insert into public.tutor_exam_runs(student_id,variant_id,revision) values(uid,v.id,v.revision) returning * into r;
  return jsonb_build_object('id',r.id);
 end if;
 if action in ('exam_save','exam_finish','exam_get','exam_reveal') then
  select * into r from public.tutor_exam_runs where id=(p->>'id')::uuid and student_id=uid for update;
  if r.id is null then raise exception 'Прохождение недоступно' using errcode='42501';end if;
  select items into snapshots from public.tutor_exam_publications where variant_id=r.variant_id and revision=r.revision;
  if action='exam_reveal' then
   if r.completed_at is null then raise exception 'Сначала завершите вариант';end if;
   select ek.keys->(p->>'task_id') into k from tutor_private.exam_keys ek where variant_id=r.variant_id and revision=r.revision;
   if p->>'part'='solution' then perform tutor_private.grant_bank_images(uid,k->>'solution');end if;
  return jsonb_build_object('answer',k->'answer','solution_doc',case when p->>'part'='solution' then nullif(k->>'solution','')::jsonb else null end);
  end if;
  if action in ('exam_save','exam_finish') then
   if r.completed_at is not null then raise exception 'Вариант уже завершён';end if;
   if jsonb_typeof(p->'answers') is distinct from 'object' then raise exception 'Проверьте ответы';end if;
   update public.tutor_exam_runs set answers=p->'answers' where id=r.id returning * into r;
  end if;
  if action='exam_finish' then
   for task in select * from jsonb_array_elements(snapshots) loop
    select ek.keys->(task->>'id') into k from tutor_private.exam_keys ek where variant_id=r.variant_id and revision=r.revision;
    if length(btrim(coalesce(r.answers->> (task->>'id'),'')))=0 then grade:='{"status":"wrong","feedback":{}}';
    else begin grade:=tutor_private.grade_answer(task,k,jsonb_build_array(r.answers->>(task->>'id'))->0);exception when raise_exception or invalid_text_representation then grade:='{"status":"wrong","feedback":{}}';end;end if;
    results:=results||jsonb_build_array(jsonb_build_object('task_id',task->>'id','status',grade->>'status'));
    if grade->>'status'='correct' then score:=score+1;end if;
    select topic_id into topid from public.tutor_modules where id=(task->>'module_id')::uuid;
    insert into public.tutor_attempts(student_id,task_id,module_id,topic_id,publication_version,answer,status,feedback,task_snapshot,is_preview,request_id,exam_run_id)
     values(uid,(task->>'id')::uuid,(task->>'module_id')::uuid,topid,(task->>'version')::integer,coalesce(r.answers->(task->>'id'),'""'),grade->>'status','{}',task,admin,gen_random_uuid(),r.id);
   end loop;
   update public.tutor_exam_runs set result=jsonb_build_object('score',score,'items',results),completed_at=clock_timestamp() where id=r.id returning * into r;
  end if;
  return to_jsonb(r)||jsonb_build_object('items',snapshots);
 end if;
 base:=tutor_private.workspace_api(action,p);
 if action='data' then
  base:=base||jsonb_build_object('modules',coalesce((select jsonb_agg(m) from jsonb_array_elements(base->'modules') m where not exists(select 1 from public.tutor_bank_tasks b join public.tutor_published_tasks t on t.id=b.task_id where t.module_id=(m->>'id')::uuid) and not exists(select 1 from tutor_private.bank_drafts d where d.module_id=(m->>'id')::uuid)),'[]'));
  return base||jsonb_build_object('bank_tasks',coalesce((select jsonb_agg(to_jsonb(t)) from public.tutor_published_tasks t join public.tutor_bank_tasks b on b.task_id=t.id where not b.deleted and t.active and ((admin and b.owner_id=uid) or (not admin and tutor_private.can_read_module(t.module_id)))),'[]'),
   'variants',coalesce((select jsonb_agg(case when admin then to_jsonb(e) else jsonb_build_object('id',e.id,'title',(select ep.title from public.tutor_exam_publications ep where ep.variant_id=e.id and ep.revision=e.revision),'revision',e.revision,'visible',true) end) from public.tutor_exam_variants e where not e.deleted and ((admin and e.owner_id=uid) or (not admin and e.visible))),'[]'),
   'exam_runs',coalesce((select jsonb_agg(to_jsonb(er) order by er.started_at desc) from public.tutor_exam_runs er where er.student_id=uid),'[]'));
 end if;
 return base;
end $$;
revoke all on function tutor_private.bank_api(text,jsonb) from public,anon;
grant execute on function tutor_private.bank_api(text,jsonb) to authenticated;
create or replace function public.tutor_api(p_action text,p jsonb default '{}') returns jsonb language sql security invoker set search_path='' as $$select tutor_private.bank_api(p_action,p)$$;
notify pgrst,'reload schema';
commit;
